{
  "case_id": "C04",
  "audience": "Coaches and sports-science students",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "Iron deficiency without anaemia turns up in roughly 15 to 35 percent of adolescent endurance athletes, depending on the ferritin threshold you use. Here's the catch: a daily iron tablet pushes hepcidin up for 24 hours or more, and that blunts absorption of the next dose.",
      "on_screen": "Title: Iron dosing in adolescent athletes. Simple graphic: daily dose spikes hepcidin, absorption of the next dose drops.",
      "claim_refs": ["SYN-C04:background:prevalence_15_to_35_percent", "SYN-C04:background:hepcidin_blunts_absorption"]
    },
    {
      "beat": "The trial",
      "narration": "So researchers tested every-other-day dosing. A double-blind randomised trial enrolled 214 athletes aged 15 to 18, all with ferritin below 30 micrograms per litre, and gave them either 60 milligrams of elemental iron on alternate days or a matched placebo, for 12 weeks.",
      "on_screen": "Trial card: double-blind RCT, n=214, ages 15-18, ferritin under 30. Two arms: 60 mg alternate-day iron vs placebo, 12 weeks. Adherence 91%.",
      "claim_refs": ["SYN-C04:abstract:design_and_population", "SYN-C04:results:dose_60mg_alternate_days_12_weeks", "SYN-C04:methods:blinding_and_adherence"]
    },
    {
      "beat": "What changed",
      "narration": "Ferritin rose 18.4 micrograms per litre on iron versus 2.1 on placebo, a between-group difference of 16.3, with a confidence interval of 12.9 to 19.7. Haemoglobin moved barely at all: 1.5 grams per litre, which is what you'd expect in athletes who weren't anaemic to begin with.",
      "on_screen": "Bar chart: ferritin +18.4 vs +2.1. Callout: difference 16.3 ug/L, 95% CI 12.9 to 19.7. Small second bar: haemoglobin +1.5 g/L, 95% CI 0.2 to 2.8.",
      "claim_refs": ["SYN-C04:results:ferritin_between_group_16.3", "SYN-C04:results:haemoglobin_between_group_1.5", "SYN-C04:discussion:small_hb_change_expected"]
    },
    {
      "beat": "The cost",
      "narration": "Gut side effects were reported by 21 of 107 athletes on iron, against 9 of 107 on placebo. A real burden, but a modest one.",
      "on_screen": "Side-by-side icon array: 21/107 iron, 9/107 placebo, gastrointestinal adverse events.",
      "claim_refs": ["SYN-C04:abstract:gi_adverse_events_21_vs_9"]
    },
    {
      "beat": "What it does and doesn't tell you",
      "narration": "Bottom line: alternate-day 60 milligram iron rebuilt stores over 12 weeks. But no performance endpoint was measured, and everyone enrolled started below 30 micrograms per litre. So this tells you about repletion in low-ferritin adolescents, not about making anyone faster.",
      "on_screen": "Two boxes. Shows: ferritin repletion in athletes with ferritin under 30. Does not show: any performance benefit. Footer: ISRCTN-SYN-C04.",
      "claim_refs": ["SYN-C04:conclusion", "SYN-C04:limitations:no_performance_endpoint", "SYN-C04:limitations:ferritin_below_30_enrolment"]
    }
  ]
}
